const LANGUAGE_COLUMNS: Readonly<Record<RegisteredUiLanguage, 1 | 2 | 3 | 4 | 5 | 6>> = {
    'en-US': 1,
    'ja-JP': 2,
    'ko-KR': 3,
    'fr-FR': 4,
    'ru-RU': 5,
    'es-ES': 6,
};

/** 返回全部运行期反馈原文，供契约测试核对源码中的真实文案。 */
export function getRuntimeFeedbackSources(): string[] {
    return runtimeFeedbackRows.map(([source]) => source);
}

/** 按界面语言展开运行期反馈词典，由各语言目录合并进 legacyText。 */
export function createRuntimeFeedbackLegacyText(language: RegisteredUiLanguage): Readonly<Record<string, string>> {
    const column = LANGUAGE_COLUMNS[language];
    return Object.fromEntries(runtimeFeedbackRows.map((row) => [row[0], row[column]]));
}
